import math

def build_agent(sandbox):
    # No modifications needed; the seeker is already present
    return None

def agent_action(sandbox, agent_body, step_count):
    seeker_body = sandbox.get_seeker_body()
    user_data = seeker_body.userData
    if user_data is None:
        user_data = {
            'activation_complete': False,
            'activation_count': 0,
            'cooldown_remaining': 0,
            'target_positions': [],
            'first_rdv_done': False,
            'second_rdv_done': False,
            'tracking': False,
            'last_heading': 0.0
        }
        seeker_body.userData = user_data
    else:
        # Update target positions for velocity calculation
        target_pos = sandbox.get_target_position()
        user_data['target_positions'].append((target_pos[0], target_pos[1]))
        if len(user_data['target_positions']) > 5:
            user_data['target_positions'].pop(0)

    seeker_pos = sandbox.get_seeker_position()
    seeker_x, seeker_y = seeker_pos
    seeker_heading = sandbox.get_seeker_heading()
    seeker_vel = sandbox.get_seeker_velocity()
    seeker_vx, seeker_vy = seeker_vel

    # Corridor and obstacle avoidance
    x_min, x_max = sandbox.get_corridor_bounds()
    if seeker_x < x_min - 0.02 or seeker_x > x_max + 0.02:
        # Adjust heading to stay within corridor
        if seeker_x < x_min:
            desired_heading = math.atan2(seeker_y - 1.5, x_min - seeker_x)
        else:
            desired_heading = math.atan2(seeker_y - 1.5, x_max - seeker_x)
        delta_angle = desired_heading - seeker_heading
        if delta_angle > 0.12:
            new_heading = seeker_heading + 0.12
        elif delta_angle < -0.12:
            new_heading = seeker_heading - 0.12
        else:
            new_heading = desired_heading
        thrust = 50.0
        fx = thrust * math.cos(new_heading)
        fy = thrust * math.sin(new_heading)
        sandbox.apply_seeker_force(fx, fy)

    # Obstacle avoidance
    obstacles = sandbox.get_terrain_obstacles()
    for obstacle in obstacles:
        if hasattr(obstacle, 'position'):
            obstacle_pos = obstacle.position
            dx = seeker_x - obstacle_pos.x
            dy = seeker_y - obstacle_pos.y
            distance_to_obstacle = math.hypot(dx, dy)
            if distance_to_obstacle < 0.05:
                desired_heading = math.atan2(dy, dx)
                delta_angle = desired_heading - seeker_heading
                if delta_angle > 0.12:
                    new_heading = seeker_heading + 0.12
                elif delta_angle < -0.12:
                    new_heading = seeker_heading - 0.12
                else:
                    new_heading = desired_heading
                thrust = 50.0
                fx = thrust * math.cos(new_heading)
                fy = thrust * math.sin(new_heading)
                sandbox.apply_seeker_force(fx, fy)

    # Activation phase
    if not user_data['activation_complete']:
        activation_zone_low = 13.0
        activation_zone_high = 17.0
        if seeker_x < activation_zone_low:
            target_activation_x = activation_zone_low
        elif seeker_x > activation_zone_high:
            target_activation_x = activation_zone_high
        else:
            target_activation_x = seeker_x
        target_activation_y = seeker_y

        dx = target_activation_x - seeker_x
        dy = target_activation_y - seeker_y
        if dx != 0 or dy != 0:
            desired_heading = math.atan2(dy, dx)
        else:
            desired_heading = seeker_heading

        delta_angle = desired_heading - seeker_heading
        if delta_angle > 0.12:
            new_heading = seeker_heading + 0.12
        elif delta_angle < -0.12:
            new_heading = seeker_heading - 0.12
        else:
            new_heading = desired_heading

        if user_data['cooldown_remaining'] > 0:
            user_data['cooldown_remaining'] -= 1
            thrust = 40.0
        else:
            thrust = 100.0

        fx = thrust * math.cos(new_heading)
        fy = thrust * math.sin(new_heading)
        sandbox.apply_seeker_force(fx, fy)

        if activation_zone_low <= seeker_x <= activation_zone_high:
            user_data['activation_count'] += 1
            if user_data['activation_count'] >= 80:
                user_data['activation_complete'] = True
        else:
            user_data['activation_count'] = 0
    else:
        # Rendezvous phase
        slots = sandbox.get_rendezvous_slots()
        in_slot = False
        for slot in slots:
            if step_count >= slot[0] and step_count <= slot[1]:
                in_slot = True
                break

        if not user_data['first_rdv_done'] and in_slot:
            target_pos = sandbox.get_target_position()
            target_x, target_y = target_pos

            if len(user_data['target_positions']) >= 2:
                prev_pos = user_data['target_positions'][-2]
                curr_pos = user_data['target_positions'][-1]
                dx = curr_pos[0] - prev_pos[0]
                dy = curr_pos[1] - prev_pos[1]
                target_speed = math.hypot(dx, dy)
                target_vel = (dx, dy)
            else:
                target_vel = (0, 0)

            if target_speed >= 0.15:
                ref_dir = (target_vel[0], target_vel[1])
                ref_dir_length = math.hypot(ref_dir[0], ref_dir[1])
                if ref_dir_length > 0:
                    ref_dir = (ref_dir[0] / ref_dir_length, ref_dir[1] / ref_dir_length)
                else:
                    ref_dir = (0, 0)
            else:
                ref_dir = (target_x - seeker_x, target_y - seeker_y)
                ref_dir_length = math.hypot(ref_dir[0], ref_dir[1])
                if ref_dir_length > 0:
                    ref_dir = (ref_dir[0] / ref_dir_length, ref_dir[1] / ref_dir_length)
                else:
                    ref_dir = (0, 0)

            desired_heading = math.atan2(ref_dir[1], ref_dir[0])
            delta_angle = desired_heading - seeker_heading
            if delta_angle > 0.12:
                new_heading = seeker_heading + 0.12
            elif delta_angle < -0.12:
                new_heading = seeker_heading - 0.12
            else:
                new_heading = desired_heading

            if user_data['cooldown_remaining'] > 0:
                user_data['cooldown_remaining'] -= 1
                thrust = 40.0
            else:
                distance = math.hypot(target_x - seeker_x, target_y - seeker_y)
                relative_speed = math.hypot(target_vel[0] - seeker_vx, target_vel[1] - seeker_vy)
                if distance > 6.0 or relative_speed >= 1.8:
                    thrust = 150.0
                else:
                    thrust = 50.0
                if thrust > 120:
                    user_data['cooldown_remaining'] = 80
                    thrust = 120.0

            fx = thrust * math.cos(new_heading)
            fy = thrust * math.sin(new_heading)
            sandbox.apply_seeker_force(fx, fy)

            if distance <= 6.0 and relative_speed < 1.8:
                angle_diff = math.degrees(abs(math.atan2(ref_dir[1], ref_dir[0]) - seeker_heading))
                if angle_diff < 55.0:
                    user_data['first_rdv_done'] = True
        elif user_data['first_rdv_done'] and not user_data['second_rdv_done'] and in_slot:
            target_pos = sandbox.get_target_position()
