    if user_data is None:
        user_data = {
            'activation_count': 0,
            'activation_complete': False,
            'cooldown_remaining': 0,
            'target_positions': [],
            'first_rdv_done': False,
            'second_rdv_done': False,
            'tracking': False,
            'total_impulse_used': 0.0
        }
        seeker_body.userData = user_data
    else:
        # Update target positions for velocity calculation
        target_pos = sandbox.get_target_position()
        user_data['target_positions'].append((target_pos[0], target_pos[1]))
        if len(user_data['target_positions']) > 5:
            user_data['target_positions'].pop(0)

    seeker_pos = sandbox.get_seeker_position()
    seeker_x, seeker_y = seeker_pos
    seeker_heading = sandbox.get_seeker_heading()
    seeker_vel = sandbox.get_seeker_velocity()
    seeker_vx, seeker_vy = seeker_vel
    remaining_budget = sandbox.get_remaining_impulse_budget()

    # Check corridor bounds and adjust heading
    x_min, x_max = sandbox.get_corridor_bounds()
    if seeker_x < x_min - 0.02 or seeker_x > x_max + 0.02:
        # Adjust heading to stay within corridor
        if seeker_x < x_min:
            desired_heading = math.atan2(seeker_y - 1.5, x_min - seeker_x)
        else:
            desired_heading = math.atan2(seeker_y - 1.5, x_max - seeker_x)
        delta_angle = desired_heading - seeker_heading
        if delta_angle > 0.12:
            new_heading = seeker_heading + 0.12
        elif delta_angle < -0.12:
            new_heading = seeker_heading - 0.12
        else:
            new_heading = desired_heading
        thrust = 50.0
        fx = thrust * math.cos(new_heading)
        fy = thrust * math.sin(new_heading)
        sandbox.apply_seeker_force(fx, fy)
        user_data['total_impulse_used'] += math.hypot(fx, fy)

    # Obstacle avoidance
    obstacles = sandbox.get_terrain_obstacles()
    for obstacle in obstacles:
        if hasattr(obstacle, 'position'):
            obstacle_pos = obstacle.position
            dx = seeker_x - obstacle_pos.x
            dy = seeker_y - obstacle_pos.y
            distance_to_obstacle = math.hypot(dx, dy)
            if distance_to_obstacle < 0.05:
                desired_heading = math.atan2(dy, dx)
